import { IOperatorTheme } from './types';

function validateProperty<T extends object>(item: T, key: keyof T, type: object | string | number) {
    if (typeof item[key] !== type) {
        throw new Error(`Operator Theme option is invalid "${String(key)}"`);
    }
}

export function validateThemeOptions(options: IOperatorTheme) {
    validateProperty(options, 'fontName', 'string');
    validateProperty(options, 'darkAccent', 'object');
    validateProperty(options.darkAccent, 'hex', 'number');
    validateProperty(options.darkAccent, 'string', 'string');
    validateProperty(options, 'midAccent', 'object');
    validateProperty(options.midAccent, 'hex', 'number');
    validateProperty(options.midAccent, 'string', 'string');
    validateProperty(options, 'lightAccent', 'object');
    validateProperty(options.lightAccent, 'hex', 'number');
    validateProperty(options.lightAccent, 'string', 'string');
    validateProperty(options, 'veryLightAccent', 'object');
    validateProperty(options.veryLightAccent, 'hex', 'number');
    validateProperty(options.veryLightAccent, 'string', 'string');
}
